SET NOCOUNT ON;
SET XACT_ABORT ON;
IF DB_NAME() NOT LIKE N'DatabaseGym[_]Pruebas%' THROW 51000,'Solo se permite cargar esta muestra en una base DatabaseGym_Pruebas.',1;
IF OBJECT_ID('dbo.Demo_Info','U') IS NOT NULL
BEGIN
 IF EXISTS(SELECT 1 FROM dbo.Demo_Info WHERE Version=N'20261026') BEGIN PRINT 'La muestra ya estaba cargada. Se conservan los cambios de las pruebas.';RETURN;END;
 THROW 51000,'Existe otra muestra en esta base. Use un nombre nuevo.',1;
END;
IF EXISTS(SELECT 1 FROM dbo.Socio) OR EXISTS(SELECT 1 FROM dbo.Clase) OR EXISTS(SELECT 1 FROM dbo.App_Sesion)
 THROW 51000,'La muestra exige una base nueva sin socios, actividades ni sesiones.',1;
DECLARE @usuario int=(SELECT Id_Usuario FROM dbo.Usuario WHERE LoginName=N'demo');
IF @usuario IS NULL THROW 51000,'Primero cree el acceso demo con el asistente.',1;
BEGIN TRANSACTION;
CREATE TABLE dbo.Demo_Info(Version nvarchar(20) NOT NULL,FechaBase date NOT NULL,CreadoUtc datetime2 NOT NULL DEFAULT SYSUTCDATETIME());
CREATE TABLE dbo.Demo_Referencia(Tipo varchar(20) NOT NULL,Codigo int NOT NULL,Id int NOT NULL,CONSTRAINT PK_Demo_Referencia PRIMARY KEY(Tipo,Codigo));
DECLARE @hoy date=CONVERT(date,GETDATE());
DECLARE @i int=1,@id int,@clase int,@socio int,@membresia int,@entrenador int,@piso int,@tipo int,@sesion int,@inicio datetime2,@fin datetime2,@estado varchar(20),@importe decimal(18,2),@desde date,@hasta date,@pago decimal(18,2);
