SET @i=1;
WHILE @i<=140 BEGIN
 SELECT @socio=Id FROM dbo.Demo_Referencia WHERE Tipo='Socio' AND Codigo=@i;
 SET @importe=CASE WHEN @i>=131 THEN 0 ELSE 26000 END;
 SET @desde=CASE WHEN @i BETWEEN 111 AND 120 THEN DATEADD(day,-60,@hoy) WHEN @i BETWEEN 121 AND 130 THEN DATEADD(day,10,@hoy) ELSE DATEADD(day,-10,@hoy) END;
 SET @hasta=CASE WHEN @i BETWEEN 111 AND 120 THEN DATEADD(day,-1,@hoy) WHEN @i BETWEEN 121 AND 130 THEN DATEADD(day,40,@hoy) WHEN @i BETWEEN 71 AND 80 THEN DATEADD(day,3,@hoy) ELSE DATEADD(day,35,@hoy) END;
 INSERT dbo.App_Membresia(Id_Socio,[Plan],Desde,Hasta,Importe,Id_Usuario) VALUES(@socio,CASE WHEN @i>=131 THEN N'DEMO Cortesía' ELSE N'DEMO Mensual' END,@desde,@hasta,@importe,@usuario);
 SET @membresia=CONVERT(int,SCOPE_IDENTITY());INSERT dbo.Demo_Referencia VALUES('Membresia',@i,@membresia);
 SET @pago=CASE WHEN @i<=80 OR @i BETWEEN 111 AND 130 THEN @importe WHEN @i BETWEEN 81 AND 100 THEN 13000 ELSE 0 END;
 IF @pago>0 INSERT dbo.App_Pago(Id_Membresia,Importe,Medio,Referencia,Id_Usuario) VALUES(@membresia,@pago,CASE WHEN @i%3=0 THEN N'Tarjeta' WHEN @i%3=1 THEN N'Efectivo' ELSE N'Transferencia' END,N'DEMO carga inicial',@usuario);
 SET @i+=1;
END;
